#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-3.0-only
# Copyright (c) 2026 Peter Csaszar (Császár Péter)
# Created: 2026-10-10
# Checks that every source file and script carries the workspace's file header.
#
# policies/source-header-model.md: after an optional shebang, a licence line,
# a copyright line naming the holder, a "Created:" line with a valid date that
# is not in the future, and a purpose line.  No e-mail address in it.  A
# generated file says so instead and has no copyright line.
#
#   check_headers.sh <source directory>
set -euo pipefail

cd "$1"
holder='Copyright \(c\) [0-9]{4} Peter Csaszar \(Császár Péter\)'
today="$(date +%F)"
failed=0 files=0
fail() { failed=$((failed + 1)); echo "FAIL: $1" >&2; }

while IFS= read -r f; do
    files=$((files + 1))
    # the header: the first lines after a shebang, comment marker removed
    mapfile -t h < <(sed -n '1,6p' "$f" | sed -e '1{/^#!/d}' | sed -e 's@^/\* \(.*\) \*/$@\1@' -e 's@^# \{0,1\}@@' | head -4)
    if [ "${#h[@]}" -lt 3 ]; then fail "$f: no header"; continue; fi
    case "${h[0]}" in
        "SPDX-License-Identifier: "*) ;;
        *) fail "$f: first header line is not the SPDX licence tag"; continue ;;
    esac
    case "$f" in
        src/width_table.c)       # generated: it says so and has no author
            grep -q '^/\* Generated by .* from .*' "$f" || fail "$f: does not say it is generated" ;;
        *)
            [[ "${h[1]}" =~ ^$holder$ ]] || fail "$f: copyright line is not 'Copyright (c) <year> Peter Csaszar (Császár Péter)': '${h[1]}'"
            if [[ "${h[2]}" =~ ^Created:\ ([0-9]{4}-[0-9]{2}-[0-9]{2})$ ]]; then
                d="${BASH_REMATCH[1]}"
                if norm="$(date -d "$d" +%F)"; then
                    [ "$norm" = "$d" ] || fail "$f: '$d' is not a date"
                else
                    fail "$f: '$d' is not a date"
                fi
                [[ ! "$d" > "$today" ]] || fail "$f: Created $d is in the future"
            else
                fail "$f: third header line is not 'Created: YYYY-MM-DD': '${h[2]}'"
            fi
            [ "${#h[@]}" -ge 4 ] && [ -n "${h[3]}" ] || fail "$f: no purpose line"
            printf '%s\n' "${h[@]}" | grep -q '@' && fail "$f: the header contains an '@' (an e-mail address?)" || true
            ;;
    esac
done < <(find . \( -path ./build -o -path ./.git \) -prune -o -type f \
              \( -name '*.c' -o -name '*.h' -o -name '*.sh' -o -name '*.cmake' -o -name '*.in' \
                 -o -name CMakeLists.txt -o -name lintian-overrides \) -print | sed 's@^\./@@' | sort)

[ "$files" -ge 60 ] || fail "only $files files found to check: the file search has gone wrong"
if [ "$failed" -ne 0 ]; then
    echo "check_headers: $failed problems in $files files" >&2
    exit 1
fi
echo "check_headers: $files files, all with a header"
